<script setup lang="ts">import {ref,onMounted} from 'vue';import {api} from '../../api';import {t} from '../../locales';import '../../styles/app.scss';const tab=ref<'news'|'points'>('news');const rows=ref<any[]>([]);async function load(){rows.value=await api.favorites(tab.value)}onMounted(load);async function choose(v:'news'|'points'){tab.value=v;await load()}</script>
<template><view class="inner-page"><view class="inner-nav"><text class="back" @click="uni.navigateBack()">‹</text><text class="nav-title">{{t('我的收藏')}}</text></view><view class="inner-main"><view class="inner-tabs"><text class="inner-tab" :class="{active:tab==='news'}" @click="choose('news')">{{t('快讯')}}</text><text class="inner-tab" :class="{active:tab==='points'}" @click="choose('points')">{{t('点位')}}</text></view><view v-if="!rows.length" class="inner-card empty-state">{{t('暂无收藏内容')}}</view><view v-for="row in rows" :key="row.id" class="list-card" @click="uni.navigateTo({url:tab==='news'?'/pages/detail/news?id='+row.id:'/pages/detail/point?id='+row.id})"><view class="list-icon">{{tab==='news'?'▤':'⌁'}}</view><view class="list-copy"><text class="list-title">{{row.title || row.coin}}</text><text class="list-meta">{{row.source || row.dir}} · {{row.time || row.status}}</text></view><text class="list-arrow">›</text></view></view></view></template>
